228	    public static Period fix(String id, Period period, PeriodRepository periods, ClaimRepository claims, ClaimLogRepository logs,
229	            PersonRepository people, RateRepository rates, SettingRepository settings, SheetRepository sheets)
230	            throws InvalidPeriodException {
