239	        BigDecimal total = new BigDecimal("0.00");
240	        for (Claim c : claims.list(id)) {
241	            Person person = byId.get(c.personId());
242	            ClaimStatus status = atEnd.containsKey(c.id()) ? atEnd.get(c.id()) : c.status();
243	            if (!Dues.countsAtEnd(c, status, person != null ? person.holds() : Holds.NONE, late.today())
