346	    public Period insert(String sheetId, String name, LocalDate from, LocalDate to) {
347	        jdbc.update("INSERT INTO period (sheet_id, name, from_date, to_date) VALUES (?, ?, ?, ?)",
348	                sheetId, name, Date.valueOf(from), Date.valueOf(to));
349	        return new Period(sheetId, name, from, to, false, null);
350	    }
