353	    public Period find(String sheetId, String name) {
354	        return jdbc.query("SELECT * FROM period WHERE sheet_id = ? AND name_key = LOWER(TRIM(?))", ROW, sheetId, name)
355	                .stream().findFirst().orElse(null);
356	    }
