364	     *  and nothing is written. */
365	    public boolean close(Period period, BigDecimal total, Map<Long, BigDecimal> personTotals) {
366	        if (jdbc.update("UPDATE period SET closed = TRUE, closed_total = ? WHERE sheet_id = ? AND name = ? AND NOT closed",
367	                total, period.sheetId(), period.name()) != 1) {
