601	        repository.lockSheet(id);
602	        List<Period> existing = new ArrayList<>(repository.list(id));
603	        List<Period> made = new ArrayList<>();
604	        for (YearMonth month = input.first(); !month.isAfter(input.last()); month = month.plusMonths(1)) {
605	            String name = month.toString();
606	            LocalDate from = month.atDay(1);
607	            LocalDate to = month.atEndOfMonth();
608	            boolean taken = existing.stream()
609	                    .anyMatch(p -> p.name().trim().equalsIgnoreCase(name) || p.overlaps(from, to));
610	            if (taken) {
611	                continue;
612	            }
613	            Period period = repository.insert(id, name, from, to);
614	            existing.add(period);
615	            made.add(period);
616	        }
617	        generated.set(new GeneratedPeriods(made));
618	    }
