package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Store the new claim under the person; with no date given it is dated the sheet's today. Its due-by is fixed now:
 *  its date plus the person's own terms (else the terms of the person's grade in force on its date (else the sheet's terms in force on its date)). Its DRAFT line starts its status log. */
public class SaveNewClaim {
    public void save(@Val ClaimInput input, @Val Person person, SheetRepository sheets, SettingRepository settings,
            ClaimRepository repository, ClaimLogRepository log, Out<Claim> claim) {
        claim.set(insert(input, person, sheets, settings, repository, log));
    }

    /** Store one new claim as the claim form does (the paste box stores each of its lines this way). */
    static Claim insert(ClaimInput input, Person person, SheetRepository sheets, SettingRepository settings,
            ClaimRepository repository, ClaimLogRepository log) {
        var date = input.date() != null ? input.date() : sheets.today(person.sheetId());
        var dueBy = date.plusDays(person.terms() != null ? person.terms()
                : settings.termsFor(person.sheetId(), person.grades().on(date), date));
        Claim added = repository.insert(new Claim(0, person.sheetId(), person.id(), input.amount(), date, input.note(),
                ClaimStatus.DRAFT, null, null, null, false, null, input.corrects(), dueBy, null, 0, null));
        log.record(added, input.user());
        return added;
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Val;

/** Record the stored add in the audit file, with the amount and date as the screen shows them. */
public class AuditClaimAdded {
    public void audit(@Val ClaimInput input, @Val Person person, @Val Claim claim, Audit audit) {
        record(input, person, claim, audit);
    }

    /** The CLAIM_ADDED line for one stored add (the paste box writes one per line it adds). */
    static void record(ClaimInput input, Person person, Claim claim, Audit audit) {
        ClaimResponse shown = ClaimResponse.from(claim);
        audit.record("CLAIM_ADDED sheet=" + claim.sheetId() + " by=" + input.user()
                + " person=" + person.name() + " amount=" + shown.amount() + " date=" + shown.date());
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** Claims by sheet, newest first. */
@Repository
public class ClaimRepository {

    private static final RowMapper<Claim> ROW = (rs, i) -> new Claim(rs.getLong("id"), rs.getString("sheet_id"),
            rs.getLong("person_id"), rs.getBigDecimal("amount"), rs.getObject("claim_date", LocalDate.class),
            rs.getString("note"), ClaimStatus.valueOf(rs.getString("status")),
            rs.getString("claim_number"), rs.getBigDecimal("settled_due"),
            rs.getString("opened_by"), rs.getBoolean("stated"), rs.getBigDecimal("stated_due"),
            rs.getString("corrects"), rs.getObject("due_by", LocalDate.class),
            rs.getObject("deferred_until", LocalDate.class), rs.getInt("proofs"), rs.getString("split_from"));

    private final JdbcTemplate jdbc;

    public ClaimRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public List<Claim> list(String sheetId) {
        return jdbc.query("SELECT * FROM claim WHERE sheet_id = ? ORDER BY id DESC", ROW, sheetId);
    }

    /** The claim on this sheet, or null when absent. */
    public Claim find(String sheetId, long id) {
        return jdbc.query("SELECT * FROM claim WHERE sheet_id = ? AND id = ?", ROW, sheetId, id)
                .stream().findFirst().orElse(null);
    }

    public Claim insert(Claim claim) {
        var keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            var ps = con.prepareStatement(
                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, corrects, due_by, split_from) VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
                    new String[] { "id" });
            ps.setString(1, claim.sheetId());
            ps.setLong(2, claim.personId());
            ps.setBigDecimal(3, claim.amount());
            ps.setObject(4, claim.date());
            ps.setString(5, claim.note());
            ps.setString(6, claim.corrects());
            ps.setObject(7, claim.dueBy());
            ps.setString(8, claim.splitFrom());
            return ps;
        }, keys);
        return new Claim(keys.getKey().longValue(), claim.sheetId(), claim.personId(), claim.amount(),
                claim.date(), claim.note(), ClaimStatus.DRAFT, null, null, null, false, null, claim.corrects(),
                claim.dueBy(), null, 0, claim.splitFrom());
    }

